async bindAssignmentTarget(i:{taskId:string;leadWorkerId:string;epoch:number;assignmentId:string;workerId:string}){
  const c=await this.db.connect();try{
    await c.query("BEGIN");await this.assertActiveLeadTx(c,i.taskId,i.leadWorkerId,i.epoch);
    const a=await c.query(`SELECT * FROM worker_assignments WHERE task_id=$1 AND external_id=$2 FOR UPDATE`,[i.taskId,i.assignmentId]);
    if(a.rowCount!==1)throw new LeadOrchestrationError("UNKNOWN_ASSIGNMENT","assignment not found");
    const assignment=a.rows[0];
    if(!assignment.spawn_request_id)throw new LeadOrchestrationError("INVALID_TARGET","assignment has no spawn request");
    const w=await c.query(
      `SELECT 1 FROM sentient_workers WHERE id=$1 AND task_id=$2 AND spawn_request_id=$3`,
      [i.workerId,i.taskId,assignment.spawn_request_id],
    );
    if(w.rowCount!==1)throw new LeadOrchestrationError("INVALID_TARGET","worker does not match assignment spawn request");
    if(assignment.target_worker_id&&assignment.target_worker_id!==i.workerId)
      throw new LeadOrchestrationError("ASSIGNMENT_OWNERSHIP","assignment is already bound to another worker");
    if(!assignment.target_worker_id){
      await c.query(`UPDATE worker_assignments SET target_worker_id=$2,updated_at=now() WHERE id=$1`,[assignment.id,i.workerId]);
      await this.event(c,i.taskId,assignment.id,i.leadWorkerId,i.epoch,"ASSIGNMENT_TARGET_BOUND",`worker:${i.leadWorkerId}`,{assignmentId:i.assignmentId,workerId:i.workerId,spawnRequestId:assignment.spawn_request_id});
      await this.auditTx(c,i.taskId,"ASSIGNMENT_TARGET_BOUND",i.leadWorkerId,{assignmentId:i.assignmentId,workerId:i.workerId,spawnRequestId:assignment.spawn_request_id,epoch:i.epoch});
    }
    await c.query("COMMIT");
    return {assignmentId:i.assignmentId,workerId:i.workerId};
  }catch(e){await c.query("ROLLBACK");throw e}finally{c.release()}
}
